import CoreText
import Foundation

/// Registers the bundled fonts at launch. The Info.plist is generated by Xcode, so this
/// replaces a `UIAppFonts` entry.
enum LiftrFonts {
    static let files = [
        "Figtree-Regular", "Figtree-Medium", "Figtree-SemiBold", "Figtree-Bold", "Figtree-ExtraBold",
        "CourierPrime-Regular", "CourierPrime-Bold",
        "PatrickHand-Regular",
    ]

    static func register(bundle: Bundle = .main) {
        for name in files {
            guard let url = bundle.url(forResource: name, withExtension: "ttf")
                ?? bundle.url(forResource: name, withExtension: "ttf", subdirectory: "Resources/Fonts")
            else {
                assertionFailure("Missing font \(name).ttf in the app bundle")
                continue
            }
            CTFontManagerRegisterFontsForURL(url as CFURL, .process, nil)
        }
    }
}
